import unittest

from mathx import factorial


class TestMathx(unittest.TestCase):
    def test_factorials(self):
        self.assertEqual(factorial(0), 1)
        self.assertEqual(factorial(1), 1)
        self.assertEqual(factorial(5), 120)


if __name__ == '__main__':
    unittest.main()
